code("diccionario = pd.DataFrame({\n 'Variable': df.columns,\n 'Tipo Python': [str(df[c].dtype) for c in df.columns],\n 'Tipo de variable': ['Temporal','Temporal','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua','Cuantitativa continua'],\n 'Unidad o significado': ['Fecha','Hora','CO de referencia (mg/m³)','Respuesta sensor CO','NMHC de referencia (µg/m³)','Benceno (µg/m³)','Respuesta sensor NMHC','NOx de referencia (ppb)','Respuesta sensor NOx','NO2 de referencia (µg/m³)','Respuesta sensor NO2','Respuesta sensor O3','Temperatura (°C)','Humedad relativa (%)','Humedad absoluta'],\n 'Utilidad propuesta': ['Orden temporal','Orden temporal','Objetivo de regresión','Entrada candidata','Contexto','Contexto','Entrada candidata','Contexto','Entrada candidata','Contexto','Entrada candidata','Entrada candidata','Entrada candidata','Entrada candidata','Entrada candidata']\n})\ndiccionario")
